<?php require_once __DIR__.'/../config/database.php';require_once __DIR__.'/../includes/security.php';sh_require_admin();$rows=$db->query('SELECT r.id,u.name,u.email,e.title,r.status,r.registered_at FROM registrations r JOIN users u ON u.id=r.user_id JOIN events e ON e.id=r.event_id ORDER BY r.id DESC')->fetch_all(MYSQLI_ASSOC);$pageTitle='Registrations | StudentHub';$assetPrefix='../';require __DIR__.'/../includes/app-header.php';?><h1>Event Registrations</h1><div class="p15-card p15-table-wrap"><table class="p15-table"><thead><tr><th>Student</th><th>Email</th><th>Event</th><th>Status</th><th>Registered</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><?php foreach(['name','email','title','status','registered_at'] as $k):?><td><?=sh_e($r[$k])?></td><?php endforeach;?></tr><?php endforeach;?></tbody></table></div><?php require __DIR__.'/../includes/app-footer.php';?>